style.css:
@-moz-document domain("character.ai") {
/* Background and General Text */
  body, .app-content {
    background-color: #f3e8ff !important;
    color: #4b0082 !important;
    font-family: 'Comic Sans MS', 'Arial', sans-serif !important;
  }

  /* Navbar */
  .top-bar, .sidebar {
    background-color: #e4d1fa !important;
    border-bottom: 2px solid #c6a4ed !important;
    color: #4b0082 !important;
  }

  /* Sidebar Elements */
  .sidebar-item {
    background-color: #e7d4fc !important;
    color: #6a0dad !important;
    border-radius: 10px !important;
    margin: 5px 0;
  }

  .sidebar-item:hover {
    background-color: #d8a7f5 !important;
    color: #ffffff !important;
    box-shadow: 0 3px 5px rgba(75, 0, 130, 0.3);
  }

  /* Chat Area */
  .chat-area {
    background-color: #f7e9ff !important;
    border: 1px solid #e0b9f2 !important;
    border-radius: 15px;
    padding: 15px !important;
    box-shadow: 0 3px 5px rgba(75, 0, 130, 0.1);
  }

  /* Messages */
  .message {
    background-color: #ffffff !important;
    border-radius: 10px;
    padding: 10px;
    margin: 10px 0;
  }

  .message.user {
    background-color: #e6cbf9 !important;
    border-left: 5px solid #c6a4ed !important;
  }

  .message.bot {
    background-color: #e4d1fa !important;
    border-left: 5px solid #d8a7f5 !important;
  }

  /* Buttons */
  .btn {
    background-color: #d8a7f5 !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: 25px !important;
    padding: 10px 20px;
    box-shadow: 0 3px 5px rgba(75, 0, 130, 0.2);
  }

  .btn:hover {
    background-color: #c489ea !important;
    box-shadow: 0 5px 7px rgba(75, 0, 130, 0.3);
  }

  /* Inputs */
  input, textarea {
    background-color: #f7e9ff !important;
    border: 2px solid #c6a4ed !important;
    color: #4b0082 !important;
    border-radius: 15px;
    padding: 10px;
  }

  /* Links */
  a {
    color: #8a2be2 !important;
    text-decoration: none !important;
  }

  a:hover {
    color: #d04aff !important;
    text-decoration: underline;
  }

  /* Header Logo */
  .logo {
    filter: hue-rotate(240deg) !important;
  }

  /* Cute Accents */
  .decorative-element {
    background: linear-gradient(135deg, #d8a7f5, #f7e9ff) !important;
    border-radius: 50% !important;
  }
}
